(220, NULL, 207, 19, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>A shopkeeper uses a <strong>800 g weight instead of 1 kg</strong> and sells at cost price. Find profit %.</p>', '', '<p>A. 20%</p>', '', '<p> B. 25%</p>', '', '<p> C. 30%</p>', '', '<p> D. 28%</p>', '', NULL, NULL, 'B', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-20 18:14:24', '2026-04-20 18:14:24'),
(221, NULL, 207, 20, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>A man buys an article for ₹400 and sells it for ₹460. Find profit %.</p>', '', '<p>10%</p>', '', '<p>12%</p>', '', '<p>18%</p>', '', '<p>15%</p>', '', NULL, NULL, 'D', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-20 18:15:55', '2026-04-20 18:21:08'),
(222, NULL, 207, 20, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>An article is sold at 25% loss for ₹750. Find cost price.</p>', '', '<p> ₹900</p><p><br></p>', '', '<p> ₹1000</p><p><br></p>', '', '<p> ₹1100</p>', '', '<p>₹1200</p>', '', NULL, NULL, 'B', NULL, NULL, NULL, '2026-04-20 18:18:06', '2026-04-20 18:18:06'),
(223, NULL, 207, 24, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>A and B can do a work in 12 days together. A alone can do it in 20 days. Total wages = ₹3600. Find B’s share.</p>', '', '<p>₹1800</p><p> </p>', '', '<p> ₹2000</p>', '', '<p>₹24000</p>', '', '<p>₹1600</p>', '', '<p>₹2400</p>', NULL, 'E', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-20 18:26:25', '2026-04-20 18:26:25');
INSERT INTO `questions` (`id`, `passage_id`, `subject_id`, `topic_id`, `parent_question_id`, `question_type`, `passage_english`, `passage_hindi`, `question_image`, `question_image_type`, `question_english`, `question_hindi`, `option_a_english`, `option_a_hindi`, `option_b_english`, `option_b_hindi`, `option_c_english`, `option_c_hindi`, `option_d_english`, `option_d_hindi`, `option_e_english`, `option_e_hindi`, `correct_option`, `solution_english`, `solution_hindi`, `youtube_link`, `created_at`, `updated_at`) VALUES
(224, NULL, 207, 25, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>A can do work in 12 days, B in 18 days. They work alternately starting with A. Find total days.</p>', '', '<p>14</p>', '', '<p>16</p>', '', '<p>15</p>', '', '<p>17</p>', '', NULL, NULL, 'B', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-20 18:28:22', '2026-04-20 18:28:22'),
(229, NULL, 207, 27, NULL, 'normal', NULL, NULL, NULL, NULL, '<p><strong>In the figure AC and BC are radii of circles. The length of AB is 8. If AC = 4, what is BC? (BC is tangent to the circle with center A.)</strong></p><p><strong><span class=\"ql-cursor\">﻿</span></strong><img src=\"https://mba.hitbullseye.com/sites/default/files/prblm-02-1.png\"></p>', '', '<p>none of these</p>', '', '<p>5√3</p>', '', '<p>5/2</p>', '', '<p>7</p>', '', '<p>5</p>', NULL, 'E', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-20 18:46:55', '2026-04-20 18:46:55'),
(230, NULL, 207, 27, NULL, 'normal', NULL, NULL, NULL, NULL, '<p><strong>A circle of radius 3 cm is drawn inscribed in a right angle triangle ABC, right angled at C. If AC is 10 Find the value of CB</strong>																</p><p><img src=\"https://mba.hitbullseye.com/sites/default/files/prblm-02-5.png\"></p>', '', '<p>10.5cm</p>', '', '<p>(20/7)√58 cm</p>', '', '<p>21/2 cm</p>', '', '<p>None of these</p>', '', NULL, NULL, 'A', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-20 18:49:03', '2026-04-20 18:49:03');
INSERT INTO `questions` (`id`, `passage_id`, `subject_id`, `topic_id`, `parent_question_id`, `question_type`, `passage_english`, `passage_hindi`, `question_image`, `question_image_type`, `question_english`, `question_hindi`, `option_a_english`, `option_a_hindi`, `option_b_english`, `option_b_hindi`, `option_c_english`, `option_c_hindi`, `option_d_english`, `option_d_hindi`, `option_e_english`, `option_e_hindi`, `correct_option`, `solution_english`, `solution_hindi`, `youtube_link`, `created_at`, `updated_at`) VALUES
(231, NULL, 206, 28, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>A is the brother of B. B is the sister of C. C is the father of D. How is A related to D?</p>', '<p>A, B का भाई है। B, C की बहन है। C, D का पिता है। A, D से कैसे संबंधित है?</p>', '<p>Uncle</p>', '<p>चाचा</p>', '<p>Father</p>', '<p>पिता</p>', '<p>Brother</p>', '<p>मेरा पहनावा है</p>', '<p>Cousin</p>', '<p>मैंने तुम्ह</p>', NULL, NULL, 'A', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-21 04:53:51', '2026-04-21 06:44:23'),
(232, NULL, 206, 28, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>P is the mother of Q. Q is the brother of R. R is the father of S. How is P related to S?</p>', '', '<p>Mother</p>', '', '<p>Grandmother</p>', '', '<p>Aunt</p>', '', '<p>Sister</p>', '', '<p>cousin</p>', NULL, 'B', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-21 04:59:20', '2026-04-21 04:59:20'),
(233, NULL, 206, 28, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>X is the wife of Y. Y is the son of Z. Z is the mother of W. How is X related to W?</p>', '', '<p>Sister</p>', '', '<p> Daughter</p>', '', '<p>Wife</p>', '', '<p>Daughter-in-law</p>', '', NULL, NULL, 'D', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-21 05:01:45', '2026-04-21 05:01:45');
INSERT INTO `questions` (`id`, `passage_id`, `subject_id`, `topic_id`, `parent_question_id`, `question_type`, `passage_english`, `passage_hindi`, `question_image`, `question_image_type`, `question_english`, `question_hindi`, `option_a_english`, `option_a_hindi`, `option_b_english`, `option_b_hindi`, `option_c_english`, `option_c_hindi`, `option_d_english`, `option_d_hindi`, `option_e_english`, `option_e_hindi`, `correct_option`, `solution_english`, `solution_hindi`, `youtube_link`, `created_at`, `updated_at`) VALUES
(234, NULL, 206, 28, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>A is the father of B. C is the sister of A. D is the mother of C. How is D related to B?</p>', '', '<p>A) Grandmother</p>', '', '<p> B) Aunt</p>', '', '<p> C) Mother</p>', '', '<p> D) Sister</p>', '', NULL, NULL, 'A', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-21 05:03:23', '2026-04-21 05:03:23'),
(235, NULL, 206, 29, NULL, 'normal', NULL, NULL, NULL, NULL, '<p>A man said, “She is the daughter of the only son of my grandfather.” How is the woman related to the man?</p>', '', '<p>none of these</p>', '', '<p>Niece</p>', '', '<p>Aunt</p>', '', '<p>Cousin</p>', '', '<p>Sister</p>', NULL, 'E', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-21 05:05:19', '2026-04-21 05:05:19'),
(236, 6, 206, 30, NULL, 'passage', NULL, NULL, NULL, NULL, '<p><strong>Conclusions:</strong></p><p><strong> I. Some doctors are specialists</strong></p><p><strong> II. Some surgeons are famous</strong></p><p><strong>Options:</strong></p><p> </p>', NULL, '<p><strong>A) Only I follows</strong></p><p><br></p>', NULL, '<p><strong> B) Only II follows</strong></p><p><br></p>', NULL, '<p><strong> C) Both follow</strong></p><p><br></p>', NULL, '<p><strong> D) None follows</strong></p><p><br></p>', NULL, '', '', 'A', NULL, NULL, NULL, '2026-04-21 05:09:59', '2026-04-21 05:09:59'),
(237, 6, 206, 30, NULL, 'passage', NULL, NULL, NULL, NULL, '<p><strong>Conclusions:</strong></p><p> I. All doctors are specialists</p><p> II. Some surgeons are not famous</p><p>Options:</p>', NULL, '<p><strong>A) Only I follows</strong></p>', NULL, '<p><strong> B) Only II follows</strong></p>', NULL, '<p><strong> C) Both follow</strong></p>', NULL, '<p><strong> D) None follows</strong></p>', NULL, '', '', 'D', NULL, NULL, NULL, '2026-04-21 05:09:59', '2026-04-21 05:09:59'),
(238, NULL, 206, 31, NULL, 'normal', NULL, NULL, NULL, NULL, '<h2>Statements:</h2><ol><li>All roses are flowers</li><li>Some flowers are garlands</li><li>No garland is plastic</li><li>All plastics are metals</li><li>Some metals are roses</li></ol><p><br></p><h2> Conclusions:</h2><p>I. Some roses are garlands</p><p> II. Some metals are flowers</p><p> III. No rose is plastic</p><p> IV. Some flowers are not plastics</p><p> V. Some metals are garlands</p><p><br></p><h2>Options:</h2>', '', '<p>A. Only I and V are possible</p>', '', '<p> B. Only II and IV follow</p>', '', '<p> C. Only III follows, I and V are possible</p>', '', '<p> D. Only I, II and V are possible</p>', '', '<p> E. Only II follows, IV is possible</p>', NULL, 'E', '<p><img src=\"data:image/png;base64,\"></p>', NULL, NULL, '2026-04-21 05:16:17', '2026-04-21 05:16:17');
